"""Runs basic whitespace cleaning and splitting on a piece of text."""
def _whitespace_tokenize(text: Any) -> object {
    text = text.strip();
    if not text {
        return [];
    }
    tokens = text.split();
    return tokens;
}

"""Checks whether CP is the codepoint of a CJK character."""
def _is_chinese_char(cp: Any) -> object {
    if (
        ((cp >= 19968) and (cp <= 40959))
        or ((cp >= 13312) and (cp <= 19903))
        or ((cp >= 131072) and (cp <= 173791))
        or ((cp >= 173824) and (cp <= 177983))
        or ((cp >= 177984) and (cp <= 178207))
        or ((cp >= 178208) and (cp <= 183983))
        or ((cp >= 63744) and (cp <= 64255))
        or ((cp >= 194560) and (cp <= 195103))
    ) {
        return True;
    }
    return False;
}

"""Write a function that takes a list of numbers and returns the cumulative sum; that
is, a new list where the ith element is the sum of the first i + 1 elements from the original list. For
example, the cumulative sum of [1, 2, 3] is [1, 3, 6]."""
def cumulative_sum(array: Any) -> object {
    res = [];
    val = 0;
    for elem in array {
        val += elem;
        res.append(val);
    }
    return res;
}

"""
    Create frequency fingerprint from list of fingerprints.
    """
def frequency_interaction_fingerprint(fp_list: Any) -> object {
    count_fp = [sum(i) for i in zip(*fp_list)];
    frequency_fp = [(float(i) / len(fp_list)) for i in count_fp];
    return frequency_fp;
}

"""Assuming format like: { GetUserByEmail(email: "someemail") { ... } }"""
def get_email_value(operation_definition: Any) -> object {
    text_after_email = operation_definition.split('email:')[1];
    unquoted_tokens = text_after_email.split('"');
    return unquoted_tokens[1];
}

"""
    Function that returns the N number of most at risk stations.
    Args:
        stations (list): List of stations (MonitoringStation).
        N (int): Length of the desired list
    Returns:
        list: List of stations (MonitoringStation).
    """
def stations_highest_rel_level(stations: Any, N: Any) -> object {
    return sorted(
        filter(lambda (x: Any) { (x.relative_water_level() is not None); }, stations),
        key=lambda (x: Any) { x.relative_water_level(); },
        reverse=True
    )[:N];
}

"""Calculates the pressure at sealevel when given a
        known altitude in meters. Returns a value in Pascals."""
def read_sealevel_pressure(pressure: Any, altitude_m: Any = 0.0) -> object {
    p0 = pressure / pow((1.0 - (altitude_m / 44330.0)), 5.255);
    return p0;
}

"""
    line is in the format distance,zipcode,city,state,gender,race,income,price
    """
def parse_line(line: Any) -> object {
    line = line.strip().split(",")[1:];
    state = str(line[2]);
    gender = str(line[3]);
    race = str(line[4]);
    income = str(line[5]);
    price = str(line[6]);
    return [state, gender, race, income, price];
}

"""Check if two array shapes are compatible for broadcasting."""
def _broadcastable_shapes(shape_1: Any, shape_2: Any) -> object {
    return all(
        ((s1 == s2) or (s1 == 1) or (s2 == 1))
        for (s1, s2) in zip(shape_1[::-1], shape_2[::-1])
    );
}

